sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var isInsert = current.operation() == 'insert';
    var statusChanged = current.status.changes();

    if (
        current.getDisplayValue('status') != 'Requested' ||
        (!isInsert && !statusChanged)
    ) {
        return;
    }

    new LabResultStateMachine().notifyLabTeam(current);
})(current, previous);
